server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    # Shared cache zone configuration
    proxy_cache_path /var/cache/nginx/apicache levels=1:2 keys_zone=apicache:10m max_size=100m inactive=1000s;

    # API service locations with caching
    location /api/service1 {
        proxy_pass http://localhost:3000/data;
